```cpp
#include <expected>
#include <iostream>
#include <string>
std::expected<int, std::string> twice(int amount) {
    if (amount < 0 || amount > 100) return std::unexpected("outside range");
    return amount * 2;
}
int main() {
    auto result = twice(4);
    if (result) std::cout << "value " << *result << "\n";
    else std::cout << "error " << result.error() << "\n";
}
